window.DAILY = {"generated_utc": "2026-11-24T01:00:10Z", "date_cn": "2026-11-24", "window_days": 3, "source": "arXiv OAI-PMH/API (cs.CV/cs.RO) · 热度加成: Hugging Face Daily Papers", "note": "所有条目直接来自 arXiv 元数据，未经人工或模型改写；预印本未经同行评审。", "tracks": {"slam": {"name": "SLAM 与状态估计", "papers": [{"id": "2611.27633", "title": "Instant-LIVO: Efficient LiDAR-Inertial-Visual Odometry with Compact Geometry and a Bounded Single-Reference-Frame Map", "authors": ["Xinrui Wang", "Ziwei Lan", "Wenbin He", "Mingjing Yang", "Yihan Zhang", "Yilin Liu", "Peiji Chen", "Wenxin Li", "Shuyi Jiang", "Yubin Lan", "Weiguang Yang"], "abstract": "LiDAR-Inertial-Visual Odometry (LIVO) is a fundamental technology for autonomous systems; however, deployment on resource-constrained platforms remains challenging due to physical limitations. This paper presents Instant-LIVO, a tightly coupled, high-speed, real-time LIVO system. The system introduces a compact geometric map based on spatial-hashed OctVox and accelerates local-neighborhood retrieval and plane fitting through cache-assisted heuristic staged K-nearest-neighbor searches. It also employs a bounded single-reference-frame visual map that adaptively updates the reference frame according to the tracking status, while using Schmidt-type uncertainty-aware photometric fusion to maintain the correlation between the reference pose and the current state. The system performs multisensor fusion through a sequential process consisting of IMU prediction, LiDAR geometric correction, and visual photometric correction. It was evaluated on 32 public benchmarks and custom datasets. While maintaining competitive accuracy on both X86 and ARM platforms, Instant-LIVO achieves average processing-speed improvements of approximately 2.3x and 2.1x, respectively, and reduces peak memory usage to approximately 1/20 and 1/13, respectively. The results demonstrate that the proposed method outperforms existing LIO and LIVO baselines in both accuracy and computational efficiency.The implementation is available at: https://github.com/Faker-0714/Instant-LIVO.git.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27633"}, {"id": "2611.27362", "title": "NormFlowSDE: Normalizing Flows for Amortized Bayesian State Estimation", "authors": ["Yi Zhang", "Lars Mikelsons"], "abstract": "Bayesian state estimators, such as Kalman filters, estimate states from noisy observations based on dynamical models. However, obtaining accurate models can be challenging when the system involves effects that are difficult to model faithfully, such as friction, impacts, and deformation in contact-rich manipulation. Uncertainty in system parameters, inputs, and disturbances, together with simplified noise models, can further introduce simulation-to-reality mismatch and degrade estimation accuracy. These limitations motivate learning a distribution over state trajectories conditioned on observations and controls without explicitly specifying the underlying physical models. We introduce NormFlowSDE, an amortized Bayesian state estimator that learns a distribution over state trajectories by combining neural stochastic differential equations with conditional normalizing flows. Its key design choice is to utilize the capability of normalizing flows to learn stochastic behavior of variables, while leveraging the continuous-time dynamics of SDEs to model the evolution of states over time. Once trained, the model draws state paths for new measurement sequences without per-sequence optimization. In addition, we connect NormFlowSDE to stochastic continuous-time dynamics by proving weak convergence of a mean-centered, drift-corrected inference scheme to an It\\^o diffusion under stated assumptions. Finally, we benchmark NormFlowSDE against direct estimators and learned particle filters based on normalizing flows on partially observed dynamical systems, including simulated systems and real-world robot datasets. The results show that NormFlowSDE attains the lowest estimation error with calibrated uncertainty intervals on both robot datasets and filters four times faster than the fastest particle filter on every dataset.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27362"}, {"id": "2611.27817", "title": "BRINA: Bottom-Referenced Inertial Navigation with AKAZE, a Sonar SLAM for Autonomous Marine Vehicles", "authors": ["Adolfo Damiano Cafaro", "Patrizio Mariani", "Roberto Galeazzi"], "abstract": "Forward-looking sonar (FLS) provides reliable underwater perception where optical sensing is limited, but its use for navigation is hindered by the unobserved elevation of each return. As a result, motion estimated directly from sonar images suffers from an unknown metric scale that is commonly resolved using a Doppler velocity log (DVL). We present BRINA (Bottom-Referenced Inertial Navigation with AKAZE), a sonar-inertial SLAM system for marine vehicles that uses the FLS as its only exteroceptive sensor. BRINA estimates the sonar altitude from the first seabed return in each beam and uses it to project matched features onto the seabed, providing metric odometry without a DVL. We further derive a bound relating the remaining scale error to seabed tilt and slope variability. The method is evaluated in simulation with an autonomous underwater vehicle, and in field experiments with uncrewed surface vehicles over ten missions, using two FLS systems under different operating conditions.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27817"}, {"id": "2611.26849", "title": "Scoliosis5K: Multimodal Gait Analysis via Clip-Conditioned RGB-Silhouette Fusion", "authors": ["Zizhao Peng", "Zihan Wang", "Zheng Lv", "Yan Wang", "Ping Li", "Fengwei An"], "abstract": "Color walking video records body boundary motion alongside clothing folds, surface appearance, and recording-environment cues. To examine what an explicit binary silhouette contributes to participant-level classification of scoliosis-related gait when a classifier already observes the paired color sequence, we construct Scoliosis5K, a multi-site collection of 4,998 corridor-walking sequences across 3,010 participant identifiers in which RGB person crops, binary silhouettes, and two-dimensional poses share each recording identifier and frame index. Our architecture uses each patch's pixel deviation from its clip mean to weight two low-rank query and value updates inside a pretrained RGB encoder, fusing the resulting video representation with a silhouette transformer sequence and regional kernel ridge scores extracted from one native-resolution RGB frame per window. Across 988 participants in five participant-disjoint cross-validation folds and three training seeds, the complete system reaches 83.77% accuracy and 79.91% macro-averaged F1, compared with 83.27% accuracy and 79.56% macro-F1 when the video RGB encoder remains frozen under identical inputs. Zeroing the silhouette vector at fixed weights shifts overall accuracy by only 0.10 percentage points while raising positive-category recall from 68.52% to 77.78% and lowering recall for both remaining categories. Macro-averaged AUROC is 0.950 across the cohort and 0.879 among participant pairs matched on acquisition site and recording-count group.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.26849"}, {"id": "2611.27289", "title": "InterBand-EMG: A Cross-Band Foundation Model for Generalizable Hand-Pose Estimation", "authors": ["Zongheng Guo", "Tao Chen", "Dalong Du", "Yijian Yang", "Heng Liu", "Lun Shu", "Chen Luo", "Junhao Tu", "Lei Shu", "Mingzhou Wu", "Yifan Liu", "Yu Zhang", "Zhenqiang Liu", "Shilei Wen", "Jie Zhou", "Manuela Ferrario"], "abstract": "Surface electromyography (sEMG) enables continuous hand-pose estimation, but learning representations that generalize across users and movements remains challenging. We introduce InterBand-EMG, which combines band-specific quantization with cross-band reconstruction and structured masked code prediction to learn transferable EMG representations for hand-pose tracking. We also introduce SynapMyo, an eight-channel EMG-to-pose dataset comprising 1,227.74 hand-hours from 499 users across 68 movement categories. Experiments on emg2pose and SynapMyo show that InterBand-EMG outperforms state-of-the-art baselines in joint-angle accuracy across all three generalization settings on both datasets. The source code and the SynapMyo dataset will be publicly released upon acceptance of this paper.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27289"}, {"id": "2611.27319", "title": "SAVIOR: Sample-efficient Adaptation of Vision-Language Models for OCR Representation", "authors": ["Akshata A Bhat", "Sharath Naganna", "Saiful Haq", "Prashant Khatri", "Krishna Chaitanya Reddy Tamataam", "Neha Arun", "Niyati Chhaya", "Pushpak Bhattacharyya"], "abstract": "Optical Character Recognition (OCR) pipelines and vision-language models exhibit high accuracy on standard OCR and document-understanding benchmarks, yet they systematically underperform on document patterns that are operationally critical in financial workflows. These patterns include vertical or rotated text, logo-embedded vendor names, fine-print regulatory clauses, degraded scans, and complex multi-column layouts. While underrepresented in public datasets, they constitute a substantial portion of real-world failure cases. We introduce SAVIOR, a sample-efficient data curation methodology that targets such high-impact failure scenarios to adapt vision-language models for robust financial OCR. We further propose PaIRS, a structure-aware evaluation metric that measures layout fidelity by comparing pairwise spatial relationships between tokens. Fine-tuning Qwen2.5-VL-Instruct with SAVIOR-Train achieves a word recall of 0.93. When the resulting layout-aware OCR output is used as context for document question answering, it attains an F1 score of 0.89, outperforming both open- and closed-source models such as GPT-4o, Mistral-OCR, PaddleOCR-VL, and DeepSeek-OCR.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27319"}, {"id": "2611.27862", "title": "OpenAHBU: Open-sourced Automatic Human Behaviour Understanding Toolkit Through Facial Behaviour Analysis", "authors": ["Zijian Wu", "Yupeng Huo", "Cheng Luo", "Yichen Huang", "Junan Long", "Haijun Lin", "Lu Liu", "Hatice Gunes", "Bernard Ghanem", "Siyang Song"], "abstract": "Automatic facial behaviour understanding (AFBU) is fundamental to various human-centred applications, yet existing academically available toolkits offer limited functionality, closed training pipelines, and weak generalisation. This paper presents OpenAHBU, a fully open-sourced, generalisable toolkit integrating 11 AFBU functions across three semantic levels: (i) short-term external facial attributes, including landmarks, blendshapes, Action Units, and expressions; (ii) short-term facial behaviour-related human psychological states, including valence/arousal and pain; and (iii) long-term facial behaviour-related psychological traits, including depression and personality. Particularly, we re-developed eight functions, where at least four deep learning models covering different computational complexities are developed for each function, providing flexible deployment on resource-constrained and high-throughput computing scenarios. More importantly, models of most functions are trained on a comprehensive corpus aggregating multiple academically available datasets, ensuring robust cross-dataset generalisability.In addition, we include a Synergistic Multi-task Enhancement (SMTE) module to efficiently and adaptively enhance each OpenAHBU function by leveraging the complementary cues contained in its most-related support function's predictions.Extensive evaluations demonstrate that our OpenAHBU outperformed existing open-source toolkits not only in functional coverage but also the predictive performances, while providing superior deployment flexibility across diverse computational scenarios.With fully publicly available training and inference scripts, pre-trained weights, user-friendly GUI, Python library, and cross-platform compatibility, our OpenAHBU provides a reproducible, scalable and extensible toolkit at https://github.com/OpenAHBU/OpenAHBU.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27862"}, {"id": "2611.26776", "title": "What Helps Language-Model Agents Review Violent Video? A Controlled Comparison with a Human Evidence Reference", "authors": ["Mohammed El Amine Mokhtari", "Matei Mancas", "Virginie Vandenbulcke"], "abstract": "Systems that flag violent video for a human operator can now be built from language models without training, by combining perception models and letting a language model decide. We ask how the observations of the perception models should reach the decision, and which evidence matters. On the XD-Violence test set (799 clips) we fix one set of perception agents (video description, object detection, sound tagging, speech recognition and speech tagging) and one reasoning model, and compare three interfaces: messages between agents, a typed evidence graph explored with tools, and flat text read in one pass; and a single audio-visual model given the raw clip. Two annotators provide a human reference that records the decision, the incident segments and whether they relied on sight, sound or speech. Flat text matches the single model (F1 0.967 against 0.968), while the graph agent and message passing are less accurate; a variant of the graph agent developed on a separate set did not close the gap, and both graph summaries and multi-turn tool use lowered accuracy. These results hold with reworded prompts and with a larger reasoning model, except that the larger model weakens message passing enough for the graph agent to beat it. Sound events improve F1 by +0.012 [+0.004, +0.021], in line with the annotators, who used sound or speech on most violent clips. Citations of stored observations are faithful, changing about half of the decisions when removed, but no more so with the graph than with flat text, and the agent pipeline costs about 3 times the GPU time of the single model. We also report two artefacts of vision-language describers that mislead pipelines built on them.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.26776"}, {"id": "2611.27181", "title": "HumanoidPose: Monocular 3D Pose Estimation for Humanoid Robots", "authors": ["Jinlin Gan", "Mingzhe Li", "Junsheng Zhang", "Zhibo Zhou", "Jiahan Geng", "Yuhua Luo", "Changwang Zhang", "Chenglu Wen", "Lan Xu", "Siqi Shen", "Cheng Wang"], "abstract": "As humanoid robots increasingly enter real-world environments, recovering their 3D whole-body pose from monocular imagery is becoming increasingly important for external state perception, motion analysis, and robot learning. However, Humanoid Robot Pose Estimation (HRPE) lies at the intersection of conventional Robot Pose Estimation (RPE) and Human Pose Estimation (HPE), while not being fully addressed by either paradigm: RPE primarily focuses on non-humanoid robots, particularly fixed-base manipulators, whereas HPE is built upon human-specific skeletal topologies, body models, and motion priors. Despite recent progress in humanoid 2D keypoint detection and HPE adaptation, humanoid-native 3D pose recovery remains insufficiently studied, and a dedicated benchmark with suitable training data and evaluation protocols is still lacking. To address this gap, we introduce Humanoids, a benchmark for monocular 3D humanoid robot pose estimation, and propose HumanoidPose, a framework for this task. Humanoids provides synthetic 3D supervision across diverse humanoid embodiments, manually annotated real-world 2D data, and real-world RGB sequences paired with robot states for 3D evaluation on a physical Roban humanoid. HumanoidPose combines human-inspired visual perception with robot articulation modeling and explicit kinematic grounding. Experiments on Humanoids and the DHRP-H1 benchmark demonstrate strong performance in articulation recovery and 3D pose estimation, including zero-shot transfer to real-world 2D and 3D evaluation. Ablation studies further show the contribution of robot-native articulation modeling and explicit kinematic grounding. The dataset and code will be publicly released to support future research in the community.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27181"}, {"id": "2611.26676", "title": "One Behavior, Out of Order: Deterministic Execution and Parallel Simulation of ROS 2 Applications", "authors": ["Chengzi Huang", "Behnam Khodabandeloo", "Duc Anh Nguyen", "Chuanchao Gao", "Wang Yi"], "abstract": "System-level simulation is widely used to validate robotic applications before hardware deployment. However, Robot Operating System 2 (ROS 2), a popular middleware for such applications, uses asynchronous publish-subscribe communication, which can make application behavior depend on scheduling and the platform. The behavior can then vary across runs and machines even with the same inputs. This nondeterminism makes faults hard to reproduce and tests unreliable. In this paper, we first give ROS 2 applications a lightweight coordination scheme in which every component, including event-driven ones, reads its inputs and writes its outputs at predefined time instants. By decoupling computation and communication, the scheme makes an application deterministic, that is, it always has one behavior for given inputs. Tests are thus repeatable, but for large applications they still take a long time. To speed up these tests, we then present an out-of-order parallel simulation algorithm. From the predefined read and write instants, it knows before the run which activations of components depend on which. It starts each activation as soon as those it depends on have finished. Finally, we implement the algorithm in a simulator that runs existing ROS 2 applications without any change to them or to ROS 2. We evaluate the simulator on industrial use cases and synthetic graphs. On the industrial use cases, it is up to 2.6 times faster than synchronous parallel simulation and needs an order of magnitude less memory for messages than asynchronous parallel simulation.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.26676"}, {"id": "2611.27338", "title": "Latent Jacobian Steer: Eliciting Contact-Rich Out-of-Distribution Behaviors from Pretrained Humanoid Controllers", "authors": ["S K Swaminathan", "Shivam Sood", "Shreyansh Kansal", "Chengyang He", "Guillaume Adrien Sartoretti"], "abstract": "Given a pretrained general latent-conditioned whole-body humanoid controller, say a behavioral foundation model (BFM), how can we elicit complex and contact-rich out-of-distribution behaviors? Raw joint-action exploration enables direct, task-specific adjustments but can disrupt coordination learned by the pretrained controller, whereas latent exploration retains that coordination but is difficult to steer toward desired physical effects. To combine the complementary strengths of these exploration spaces, we propose Latent Jacobian Steer (LJS), which couples sampling in direct joint-action space with the semantics of the learned frozen controller's input latent space. For a task specified through desired physical effects, we sample task-relevant joint-action perturbations and map them through a damped local inverse of the policy Jacobian to obtain candidate latent ($z$) commands. These commands are executed through the frozen pretrained policy, while exploration is directed toward the physical outcomes required by the new task. Candidate outcomes are evaluated in simulation and composed into latent-command sequences that accomplish the task. Ablations show that neither action-space nor latent-space exploration alone provides the same capability as their coupling. Across diverse out-of-distribution tasks, simulation-based searching using this method produces contact-rich behaviors, including hurdling, manipulating articulated objects, and opening doors through non-prehensile contact. Over ten seeds, LJS completes more of each humanoid task than when searching in either space alone. Beyond humanoids, it also steers a goal-conditioned dexterous hand policy through four assembly tasks better than searching in goal space directly.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27338"}, {"id": "2611.27552", "title": "S-BFM: A Behavioral Foundation Model for Humanoid Control from Sparse Spatiotemporal Goals", "authors": ["Kun Yang", "Xuanyu Chen", "Jing Tan", "Yanjing Liu", "Yubo Zhao", "Renjing Xu", "Addison Lin Wang"], "abstract": "General-purpose whole-body trackers can execute diverse humanoid motions, but they require dense reference trajectories. However, tasks usually specify only where, in which posture, and when the robot should arrive, leaving the motion in between to a separate planner. Inspired by human motor coordination, our key idea is that a low-level controller can organize the intervening motion and its pace by itself from sparse goals with arrival times. In this paper, we propose S-BFM, a novel behavioral foundation model superior in its autonomy: it generates whole-body transitions from target postures, poses, and arrival times alone. Specifically, we first introduce Spatial Grounding, which adds world-frame position and heading to a forward-backward behavior representation through spatial reconstruction. Then, Time-Conditioned Distillation is designed to learn transitions and pace from real motion through closed-loop imitation of a dense-reference teacher. Lastly, Generative Fine-Tuning is introduced to broaden the covered distances and arrival times with a distilled motion generator. In simulation, S-BFM lowers global joint-position error by over 32% relative to the best baseline under fixed and mixed horizons, and raises fixed-goal reach from 43.5% to 74.6% while cutting terminal position error from 1.67 to 0.26 m. We further deploy S-BFM on the full-size AGIBOT A3 humanoid. Sparse spatiotemporal goals thus suffice for natural, well-timed whole-body motion.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27552"}]}, "rep": {"name": "三维表示与重建", "papers": [{"id": "2611.27407", "title": "BladeR: Scalable, Shape-Guided 3D Reconstruction of Wind Turbine Blades from UAV Imagery", "authors": ["Jonathan Sterckx", "Michiel Vlaminck", "Hiep Luong"], "abstract": "The structural integrity of wind turbine blades is critical for safe, efficient energy production. Accurate 3D reconstruction allows precise localization and quantification of wear and early damage detection. While drone-based inspections are standard, their high-resolution imagery poses challenges such as weak texture, lighting variability, and high computational cost. We present BladeR, a scalable pipeline for high-quality 3D reconstruction from inspection imagery. A hierarchical sparse reconstruction strategy leverages GPS/IMU data and blade shape priors to guide advanced keypoint matchers on full-resolution images. For dense reconstruction, a tiled Gaussian Splatting framework processes 45 MP images at native resolution, isolates the blade from background, and adaptively enhances detail recovery along the leading edge. Validation against commercial and open-source baselines shows significant improvements in model completeness and detail.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27407"}, {"id": "2611.27719", "title": "VeilGS: Solving Darkness as a Veil of 2D Basis Maps over Retinex 3DGS", "authors": ["Mohab Kishawy", "Chengzhou Tang", "Shahram Shirani", "Jun Chen"], "abstract": "In a dark capture, the darkness is not uniform. How much light reaches a surface depends on where it lies relative to the few light sources, and the camera compresses what remains with a tone curve. Most low-light 3D reconstruction methods either apply one curve to every pixel of a view, so a dark object beside a lamp and a bright one in an unlit corner receive the same correction, or store the darkness in the 3D representation, where it can absorb scene detail. We present VeilGS, a 3D Gaussian Splatting method for low-light novel view synthesis that treats the degradation as a veil drawn over a clear scene. Each Gaussian carries an albedo and a shading latent instead of spherical harmonics, separating surface colour from illumination. Each view is darkened by a spatially varying gain followed by a global tone curve, and rendering without this veil gives the restored scene. A small network predicts a coarse basis for the gain from the observation, and its coefficients are solved for each view rather than learned. Training through this solve discourages the Gaussians from absorbing what the veil can explain. VeilGS needs no paired normal-light supervision and stores no per-view parameters. On Gaussian-DK, its restored renders score best on no-reference NIQE and CLIP-IQA and are rated highest in a blind user study with 55 participants. On LOM, it achieves results competitive with the state of the art.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27719"}, {"id": "2611.26715", "title": "SCATR-ITS: a scalable transformer for large-area individual tree segmentation from LiDAR point clouds", "authors": ["Lassi Ruoppa", "Verneri Sepp\\\"anen", "Antero Kukko", "Juha Hyypp\\\"a"], "abstract": "Individual tree segmentation (ITS) from LiDAR point clouds is one of the most widely studied segmentation tasks in forestry. Although deep learning methods define the state of the art on the majority of ITS benchmarks, their high computational complexity and long runtime currently prevent their adoption in large-scale operational workflows. In this work, we present SCATR-ITS, a scalable transformer model specifically designed for efficient ITS over large geographical areas. Based on the ForestFormer3D framework, SCATR-ITS transitions to superpoint-level processing to accelerate inference, with the superpoints constructed from learned embeddings. The architecture incorporates size-aware superpoint-level postprocessing, a dynamic query count module to handle high variation in forest structure, and a maximal input stride designed to minimize prediction redundancy. SCATR-ITS achieves accuracy on par with the state of the art on the FGI-EMIT and FOR-InstanceV2 datasets with an up to 8.5$\\times$ higher inference speed. In addition, SCATR-ITS has a significantly lower GPU VRAM footprint during both training and inference, and exhibits excellent zero-shot generalization across multiple datasets. To demonstrate large-area ITS capabilities, SCATR-ITS is applied to a 142 km$^2$ region of Finnish national laser scanning data where it achieves an average throughput of 13.8 min/km$^2$, $\\sim$18.6$\\times$ faster than ForestFormer3D and approaching the speed of the unsupervised watershed algorithm, which it vastly outperforms in accuracy and segment quality. Overall, SCATR-ITS delivers state-of-the-art accuracy at speeds where operational-scale adoption becomes viable, paving the way toward countrywide deployment. The source code for SCATR-ITS and pretrained weights are available at https://github.com/ruoppa/scatr_its.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.26715"}, {"id": "2611.26783", "title": "CADENCE:Temporally Coherent Whole-Body Human Mesh Recovery that Preserves Expressive Hand Motion", "authors": ["Keniel Peart", "Jagmohan Chauhan", "Indu P. Bodala", "Shelly Vishwakarma"], "abstract": "Whole-body SMPL-X estimators recover body, hand, and face meshes from single images, but applied frame by frame to video they produce jittery motion. Smoothing the output removes the jitter at a cost that body-only benchmarks do not measure: a temporal filter strong enough to steady the torso also flattens the fast finger strokes that carry meaning in sign language and gesture. We present CADENCE, a whole-body SMPL-X system for monocular video designed around this trade-off. A per-frame estimator built on a shared C-RADIOv4 encoder, with a high-resolution hand pathway that reuses the same encoder on hand crops, produces each frame's estimate. An offline temporal refiner then filters the SMPL-X rotation sequence: attention along the kinematic tree selects, for every joint and every frame, a mixture of learned zero-phase filters, so the torso is smoothed while fast finger strokes pass through. On 3DPW, the refiner reduces acceleration error from 17.4 to 5.4 mm/s2 while lowering PA-MPJPE from 41.9 to 40.2 mm; generic smoothers applied to the same predictions reach 6.2 to 7.7 mm/s2. On SignAvatars/How2Sign sign-language sequences, the refiner has the lowest hand jitter among the compared smoothers while keeping a hand-speed peak amplitude of 0.98, against 0.35 for a SmoothNet retrained on the full SMPL-X vector. The per-frame estimator also obtains the lowest full-body mesh error (25.7 mm) and hand joint error (8.3 mm) among the compared methods on EHF.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.26783"}, {"id": "2611.27060", "title": "Rethinking Cross-Sensor Domain Adaptation for Bridge Point Cloud Semantic Segmentation", "authors": ["Linghui Huang", "Zipeng Wang", "Shunjie Chen", "Peng Guan", "Jiandong Wang", "Siqing Li", "Luming Yang"], "abstract": "Segmentation models for bridge point clouds lose accuracy when trained on terrestrial laser scanning (TLS) data and applied to mobile laser scanning (MLS) data. This study re-examines the SemanticBridge TLS-to-MLS protocol to determine how sampling density, surface roughness, color, and acquisition viewpoint are expressed in the 8-cm sparse-voxel representation, and how adaptation gains depend on source-model convergence. Using one sparse-convolution U-Net, we combine raw-point statistics with controlled input perturbations and compare adaptive batch normalization, entropy minimization, Mean Teacher, and confidence-filtered self-training under 100- and 300-epoch schedules. TLS and MLS have similar nearest-neighbor spacing after preprocessing (12.08 and 12.02 mm), and a 4-mm perturbation of TLS points changes voxel occupancy by only 4.4%. Color distributions differ systematically, but zeroing color on identical voxels changes target mean intersection over union (mIoU) by only +0.02, and by +0.06 after the color augmentation is scale-corrected. The sensors also observe different portions of the bridge, yielding different class proportions. A 300-epoch source-only model obtains 57.80 mIoU on the paired-bridge protocol. Confidence-filtered self-training improves the 100-epoch baseline, but from a converged model it changes target mIoU by -0.97 (source-selected checkpoints) and -2.44 (final-50-epoch means). Repeated evaluation (standard deviation 0.27-0.64) and seed variation (1.88 across three seeds) are comparable to several method differences. Adaptation results on this benchmark therefore depend on representation scale, source-model convergence, and evaluation variability.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27060"}, {"id": "2611.27281", "title": "GAAFormer: Geometry-Anchored Attention Transformer for Joint Point Cloud Denoising and Upsampling", "authors": ["Haoxi Tian (School of Civil Engineering", "Geomatics", "Southwest Petroleum University)"], "abstract": "Point cloud denoising and upsampling require samples that accurately recover the underlying surface from noisy or sparse observations. A central challenge in both tasks is preserving surface coverage while refining point locations. We introduce GAAFormer (Geometry-Anchored Attention Transformer), a unified generative octree transformer that performs both tasks with a shared network. Its decoder anchors attention neighborhoods to geometry, providing spatial context for occupancy prediction and point generation. Fixed voxel windows and alternating shifts preserve the grouping of surviving nodes as the output tree changes. The design retains the encoder, positional encoding, prediction heads, and parameter count of a serialized-attention backbone. We establish a deletion-consistency property of the neighborhood rule and evaluate both tasks using the same model. On PUNet, GAAFormer achieves a mean Chamfer distance (CD) of $6.0643\\times10^{-5}$, reducing CD and Hausdorff distance by 3.35% and 19.34%, respectively, relative to the serialized backbone. For upsampling, it achieves CD values of $0.8475$, $1.7057$, and $1.0147$ ($\\times10^{-5}$) on PU-GAN, PU1K, and Sketchfab, respectively, with improvements in CD, Hausdorff distance, and point-to-surface distance over the same backbone on PU-GAN and Sketchfab. These results establish a single architecture for point cloud denoising and upsampling. Within the shared encoder-decoder, the same geometry-anchored attention module improves both noise removal and dense point generation without task-specific redesign or additional parameters.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27281"}, {"id": "2611.27512", "title": "PGS-PCQA: Perceptually Gated Synthetic Supervision for No-Reference Point Cloud Quality Assessment", "authors": ["Qinyuan Fan", "Meng Zhang", "Clemens G\\\"uhmann"], "abstract": "Existing no-reference point cloud quality assessment (NR-PCQA) methods perform well within individual datasets but generalize poorly across datasets. We identify insufficient distortion coverage in training data as a key cause: on unseen distortion types, models rank severity levels near chance or even in reverse. We propose perceptually gated synthetic supervision for no-reference point cloud quality assessment (PGS-PCQA), an NR-PCQA model trained with synthetic distortion ranking. It builds a synthetic distortion bank from source reference point clouds and uses within-type severity ranking as supervision in addition to the source mean opinion scores (MOS), requiring no subjective scores for the synthetic samples. Since higher severity does not always mean lower perceived quality, a perceptual gate softens the ranking targets of pairs with small perceptual differences in rendered views. The synthetic supervision is used only during training and needs no target-domain data. In a single training run on SJTU-PCQA, PGS-PCQA achieves Spearman rank correlation coefficients (SRCCs) of 0.709 on WPC and 0.751 on BASICS. The corresponding published DSP-PCQA scores are 0.595 and 0.723. Under reference-disjoint cross-validation, PGS-PCQA achieves SRCCs of 0.955 on SJTU-PCQA, 0.934 on WPC, 0.906 on BASICS, and 0.791 on LS-PCQA Part I. In the exclusion experiment, the reported scores for the reduced synthetic bank represent 58-65% of the full-bank SRCC gain relative to training without the bank. Code is available at https://github.com/Fan-QY/PGS-PCQA.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27512"}]}, "ff": {"name": "前馈几何（VGGT 一系）", "papers": [{"id": "2611.27901", "title": "QuantStream3D: Geometry-Aligned Low-Bit KV Cache Quantization for Streaming Visual Geometry Transformers", "authors": ["Zunhai Su", "Keyu Fan", "Ruishan Guo", "Zhongzhu Zhou", "Jingzehua Xu", "Bohan Sun", "Hansen Feng", "Ruihan Hu", "Yik-Chung Wu", "Ngai Wong"], "abstract": "Streaming visual geometry transformers retain historical key-value (KV) states as cross-view geometric memory, but growing caches constrain long-sequence inference. We systematically characterize KV quantization in streaming geometry and uncover two linked challenges: Nonuniform Geometric Sensitivity and Cache-Geometry Mismatch. Quantization sensitivity varies across precision choices and cache locations, while perturbed retrieval changes geometry-head inputs and propagates through subsequent predictions and KV writes. Guided by these findings, we propose QuantStream3D, to our knowledge the first dedicated KV quantization framework for streaming visual geometry transformers. Geometry-Guided Mixed-Precision KV Quantization protects sensitive cross-view evidence, while Geometry-Aligned Quantization-Aware Distillation jointly adapts transformer blocks and geometry heads on student-generated quantized history. Across five benchmarks and two backbones, QuantStream3D achieves near-lossless geometric accuracy in most settings with predominantly 2-bit KV caches, and many configurations surpass unquantized inference. Compared with LLM-oriented KV quantizers, it reduces TUM absolute trajectory error and NeuralRGBD completeness error by up to 57.4% and 69.7%, respectively. Integration with existing native cache-pruning methods further pushes compression while improving reconstruction quality on NeuralRGBD. Our optimized StreamVGGT backend achieves $5.05\\times$ physical KV compression and 23.1% lower latency at batch size one. Under a fixed memory budget on the same GPU, it supports $5.4\\times$ the maximum batch size and up to $1.67\\times$ the peak throughput of unquantized inference. Code and pretrained checkpoints will be made publicly available.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27901"}, {"id": "2611.26726", "title": "Decomposing images in a PRISM: A Single-Source Multi-View Framework for Image Representation", "authors": ["Eduardo Campos", "Willam Cardoso", "Diego Furtado", "Solange Oliveira", "Alneu Lopes"], "abstract": "Multi-view learning has shown that combining complementary views can improve predictive performance, yet many datasets provide a single raw source of information. How can multiple useful views be constructed from one source? We propose PRISM (Plural Representations of Images via Structural Maps), a framework that transforms an image into representations with distinct inductive biases through explicit structural maps, together with a protocol for measuring what each view contributes. We evaluate PRISM-HD, a hand-designed instantiation of PRISM in which the constructed views are summarized through representation-specific descriptors, on three artistic and four non-artistic image datasets. Analyses at a fixed feature budget show that the gains of the structural views are not explained by feature dimensionality alone. PRISM-HD by itself outperforms WND-CHARM on all seven datasets. Moreover, PRISM-HD and Fisher Vector provide complementary predictive signals: their equal-weight combination improves over the better individual representation by 5--8 percentage points on the artistic datasets. When combined with fine-tuned deep networks through a fixed parameter-free fusion rule, the PRISM-based representation improves performance on four of seven datasets and leaves it statistically unchanged on the remaining three, indicating that the constructed views provide predictive signals that are complementary to learned deep representations.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.26726"}, {"id": "2611.26779", "title": "Tracktail: Multi-View 3D Point Tracking without Depth Input", "authors": ["Katie L Rupp", "Jonathan Wong", "Sharmishtaa Seshamani", "Ana Mafalda Vicente", "Lili Karashchuk"], "abstract": "We introduce Tracktail, a novel architecture designed to efficiently track query points in 3D from multiple calibrated views without any depth input. Our architecture separates the task as a per-camera video encoding of features and a per-query decoder. Notably, camera cross-attention is only performed across queries in the decoder, allowing for efficient inference (7 FPS and less than 4 GB memory for 10 views and 100 query points). We further introduce a per-camera scene scale computed from camera geometry, which allows us to normalize inputs and predictions appropriately across a vast variety of dataset scales. We train on a synthetic Multi-View Kubric dataset as well as a novel Multi-View Point Odyssey benchmark dataset, which consists of synthetic renders of humans and animals across 499 frames. Tracktail achieves state-of-the-art results on the Panoptic Studio, DexYCB, and Multi-View Kubric benchmarks, outperforming methods that rely on estimated depth. Tracktail also demonstrates a strong ability to maintain accurate tracking over longer ranges compared to existing methods. Our code, data, and weights are publicly available: https://ai-hhmi.github.io/tracktail/", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.26779"}, {"id": "2611.27621", "title": "Automating Multi-View Quality Assessment of 3D Annotation Layouts", "authors": ["Hongyi Yang", "Jinao Wu", "Yanwei Zhang", "Shengwen Fu", "Haibin Ling", "Bingyao Huang", "Jingwei Qu"], "abstract": "Text labels provide descriptive information about elements in visual scenes. In 3D visualization, the arrangement of these labels and their connections to target locations forms an annotation layout. Assessing layout quality supports comparisons between alternative layouts. However, existing quality measures often focus on specific layout properties and may not fully reflect human judgments of overall quality. Moreover, a layout may appear clear from one viewpoint but suffer from occlusion or clutter from another. To address these issues, we propose a multi-view quality assessment method based on a multimodal large language model (MLLM). We fine-tune a compact MLLM using structured supervision from human ratings to predict a rating for each quality dimension in each view. These ratings are aggregated into view-level and sample-level quality scores. To support training and evaluation, we construct the Annotation Layouts with Quality Assessment (ALQA) dataset, containing 3,216 layout samples from 1,072 3D objects across 13 categories. Each layout is rendered from 5 predefined viewpoints, and each view is independently rated by 3 human raters across 5 quality dimensions. On ALQA, our method agrees more closely with human reference scores than the evaluated MLLM baselines, and a user study demonstrates strong agreement with human preferences in layout ranking.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27621"}, {"id": "2611.27822", "title": "Underwater Spectral Recovery via Multi-View Hyperspectral Imaging", "authors": ["Jonathan Sterckx", "Alice James", "Avishkar Seth", "Laurens Diels", "Michiel Vlaminck", "Jan Aelterman", "Endrowednes Kuantama", "Hiep Luong"], "abstract": "Underwater imaging suffers from wavelength-dependent absorption and scattering that distort scenes and obscure spectral signatures. While RGB restoration improves visual clarity, the outputs remain broadband and tied to the sensor's color space. We introduce a physically grounded framework that lifts underwater restoration to continuous spectral radiance using multi-view hyperspectral imaging. By representing continuous spectra via low-rank basis functions and leveraging multi-distance observations, our framework jointly constrains scene radiance and water parameters. We employ a robust sparse-to-dense pipeline: water parameters are estimated from consistent multi-view matches and then applied globally to invert the light transport model across the full images. Validated on physics-based synthetic data rendered via the Mitsuba 3 spectral path tracer, our method recovers physically meaningful radiance spectra and, as a downstream application, outperforms standard image restoration baselines.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27822"}]}, "wm": {"name": "世界模型", "papers": [{"id": "2611.27963", "title": "Non-penetrating World Models", "authors": ["Yuhang Dai", "Yinwei Wu", "Ziyue Lin", "Han Ji", "Xingyi Yang"], "abstract": "We study a new problem of preventing object penetration in interactive video world models. To understand how existing models handle this, we introduce NoPeBench, a benchmark that evaluates how world models respond to physical obstacles. Our evaluation reveals that none of the open-source models can reliably prevent such failures. Surprisingly, however, these models already encode the information needed to predict such violations. We find that the hidden states of diffusion transformers (DiTs) can predict whether a candidate action will penetrate an obstacle. Building on this, we introduce NoPeWorld, a lightweight framework that detects and prevents penetration. Specifically, we train a small prediction head on top of a frozen DiT's hidden states to read out if a candidate action is safe or not. Unsafe actions are then replaced with safe ones that best preserve the original intent. Despite its simplicity, NoPeWorld substantially reduces the physical violation rate, averaged over six video world models, from 74% to 16%. Remarkably, our method shows zero-shot generalization to open-domain imagery, third-person viewpoints, and moving obstacles. We publicly release our code, the NoPeBench benchmark, and model weights. Project Page: https://nopeworld.github.io .", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27963"}, {"id": "2611.26825", "title": "Skill-JEPA: Learning Planner-Aligned Action Spaces for World Models", "authors": ["Tom\\'as Couso Coddou", "Christ Devia", "Rex G. Liu", "Rodrigo Toro Icarte"], "abstract": "World models based on Joint-Embedding Predictive Architectures (JEPAs) learn from pixels to predict the outcome of actions in a latent space. To reach a goal, a planner samples many candidate action sequences, uses the model to predict where each one leads, and executes the best one. However, standard planners draw their candidates from a Gaussian, while the model has only seen the structured, state-dependent actions of its training data. Its predictions for such candidates are unreliable, and planning fails more often as goals move farther away. We propose Skill-JEPA, which learns an action space aligned with the planner. A variational autoencoder conditioned on the current state encodes short action sequences into latent skills with a standard Gaussian prior, and decodes them back into actions. The world model predicts the effect of skills rather than raw actions, and the planner searches over skills starting from that same Gaussian, so its candidates resemble the model's training data. Skill-JEPA adds a single module, trained end-to-end with the world model, and leaves the planner untouched, with no subgoals, hierarchy, or hand-designed skills. Across three JEPA world models and four benchmarks, average success on goals 80 steps away rises from 42% with raw actions to 62%; the gains grow with goal distance and hold across four planners. On AntMaze, a quadruped locomotion task, success on goals two maze cells away rises from 0.4% to 38%. This suggests that part of the difficulty of reaching distant goals lies in the action space, and can be removed without changing the planner.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.26825"}, {"id": "2611.26867", "title": "SonoAtlasWorld: Anatomy-Grounded Ultrasound World Models for Wide-Range Scanning", "authors": ["Zheyuan Zhang", "Boris Mailhe", "Hang Yu", "Yikang Liu", "Xiao Chen", "Ankush Mukherjee", "Terrence Chen", "Shanhui Sun"], "abstract": "Learning robotic ultrasound policies requires interactive environments for scalable data generation and repeatable evaluation, while exploration on real patients is limited by acquisition costs and safety constraints. Generative world models offer an alternative, but image history and probe actions alone do not ensure anatomical consistency across wide-range scans and changing acoustic windows. We introduce SonoAtlasWorld, an ultrasound world model built on anatomy as state. A persistent 3D anatomical asset extracted from computed tomography (CT) anchors each scan to a specific anatomy. Probe actions determine anatomical and acoustic visibility conditions for a causal ultrasound generator trained on clinical videos. Our three-stage pipeline combines anatomy-conditioned pretraining, causal conversion and long-rollout alignment. Inference optimizations achieve pose-to-ultrasound throughput of 81.2 FPS. To evaluate anatomical control beyond image similarity, we introduce the Action-Following Index (AFI), which measures normalized reconstruction gain over a static-prefix baseline. On 40 held-out 3D volumes, SonoAtlasWorld achieves liver and macro-organ AFI of 0.428 and 0.262, compared with at most 0.117 and 0.038 for the tested action- and geometry-conditioned methods. Long-rollout alignment reduces brightness drift by 3.46x at the end of 40 repeated scan cycles. SonoAtlasWorld also generates offline policy-training demonstrations and supports anatomically grounded closed-loop evaluation. Scaling the generated training data improves key-plane acquisition success from 48.2% to 81.2% on unseen anatomies in simulation, demonstrating its utility for robotic ultrasound policy learning.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.26867"}, {"id": "2611.26981", "title": "ViewDreamer: A Robot World Model beyond Fixed Camera Setups", "authors": ["Ye Mao", "Jinhui Xiong", "Egor Larionov", "Shiyang Lu", "Krystian Mikolajczyk", "Wei Ye"], "abstract": "Video generation models are increasingly important for robot learning, yet most generate each camera view separately or tile all views in a fixed layout. Robot demonstrations, however, are captured by synchronized cameras whose number, placement, and order vary across embodiments. We present ViewDreamer, a single world model that handles variable sets of cameras by disentangling per-view generation from cross-view interaction. Each view follows the generation path of a pretrained single-view model, and views interact only through shared slot tokens. We stabilize multi-view training with a curriculum that gradually increases the number of views. Cross-View Slot Agreement uses visual foundation models to group geometrically and semantically similar regions across views into shared slots. On RoboView-Bench, which covers one to four cameras, ViewDreamer achieves the best generation quality among the models evaluated and improves cross-view consistency over independent per-view generation. These gains carry over to our world-action model (WAM) and action-conditioned world model (AC-WM). Our WAM outperforms the FastWAM-Joint baseline on LIBERO-Plus, RoboTwin 2.0, and RoboDojo, and on a real Franka robot. Both variants improve out-of-domain generalization to various camera settings and scenes.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.26981"}, {"id": "2611.27024", "title": "ReactDrive: Self-Reactive Driving World Model", "authors": ["Yifan Wang", "Xiaoqi Wang", "Cho-Ying Wu", "Wenbin He", "Chenyu You", "Liu Ren"], "abstract": "The world evolves through the dynamics of its constituent entities and their interactions, with changes in one entity influencing the behavior of others. To simulate this evolution under different actions, interactive world models need to capture the resulting agent responses as part of the world's own dynamics. In autonomous driving, errors in modeling these responses can misrepresent maneuver safety and undermine the reliability of generated videos used for policy evaluation and learning. To formalize this intrinsic requirement for driving world model, we define self-reactivity as the capability to model agent responses from observed history and a specified ego action, and generate visual futures that reflect those responses without prescribed future agent trajectories. To realize this capability, we introduce ReactDrive, a driving world model that jointly learns agent dynamics and visual generation through a shared agent state representation. Within this framework, dynamics supervision grounds a reactive dynamics prior in observed agent states, while the video objective jointly optimizes the self-reactivity and visual realism. Experiments show improved agent responses, ego controllability, and video quality, a 96.0% preference for agent reactivity in human comparisons across five baselines, and better downstream planning through augmentation with generated videos. We hope this work encourages the community to recognize self-reactivityas a foundational capability for developing and evaluating interactive world models. Project page: https://reactdrive.github.io/ .", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27024"}, {"id": "2611.27515", "title": "Beyond a Single Human Demonstration: Learning from Scored Trajectory Alternatives for End-to-End Driving", "authors": ["Xinyao Rao", "Zecheng Tang", "Liuxuan Sun", "Zheyuan Lai", "Minjun Yu", "Xun Cao", "Wei Li"], "abstract": "Human driving logs record only one trajectory per scene, leaving other feasible driving choices without explicit trajectory targets or quality labels. This limits supervision for end-to-end planners that generate and refine multiple candidate trajectories. Meanwhile, conditioning refinement on a large vision-language model adds substantial online inference cost. We propose DriveSTA, which extends autoregressive proposal generation and proposal-conditioned residual flow refinement with scored trajectory alternatives. For each training scene, we generate alternatives offline through smooth deformations of the recorded trajectory and evaluate their simulated execution against logged traffic. Diverse, high-quality alternatives supervise distinct proposals and define residual targets for quality-guided denoising, while candidates spanning the full score range train a scorer to assess driving quality. A shared joint-embedding predictive architecture (JEPA), adapted through masked video-feature prediction, encodes observed frames once and provides temporal context for both refinement and scoring. On NAVSIM v1 Navtest, DriveSTA ranks first among the compared planners trained on NAVSIM data alone. With expanded training data, DriveSTA-Scale achieves state-of-the-art results among the compared methods on Navtest and closed-loop HUGSIM, while reducing mean planner forward-pass latency by 73% relative to ChainFlow-VLA in matched evaluations.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27515"}, {"id": "2611.27516", "title": "PhiJEPA: Denoising Latent Predictions for Visual Representation Learning", "authors": ["Makoto Yamada", "Yao-Hung Hubert Tsai"], "abstract": "Can a predictor trained to infer hidden image regions still help a world model plan when part of an object disappears from view and the visible context is blurred? We introduce PhiJEPA, a joint-embedding predictive architecture that adapts PhiNet's two-stage prediction to masked Transformers. From sparse, photometrically corrupted context, a Transformer block predicts hidden tokens of an independently corrupted teacher view. A token-wise MLP then maps these predictions to clean teacher tokens. Controlled ablations show that the combined objective improves dense features over the tested one-stage alternatives. Pre-trained on ImageNet-1K with $5.6\\times10^{19}$ training FLOPs, PhiJEPA achieves 69.3 mIoU on linear PASCAL VOC segmentation, exceeding the evaluated I-JEPA and DSeq-JEPA checkpoints in segmentation accuracy, with 25\\% fewer training FLOPs than I-JEPA. It also improves hidden-region segmentation over Simple I-JEPA (49.1 vs.\\ 44.3 mIoU). As an application, we use the frozen encoder in DINO-WM on PushT, and reuse the pre-training predictor, which JEPAs usually discard, to complete occluded tokens without fine-tuning. In open-loop planning with simultaneous object occlusion and Gaussian blur ($\\sigma=2$ pixels), predictor completion raises success from 33\\% to 65\\%, compared with 25\\% for Simple I-JEPA with its predictor and 40\\% for iBOT with pixel inpainting. Together, these results support two-stage latent prediction as an efficient approach to learning visual representations that remain useful under photometric degradation and support completion under partial observation.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27516"}, {"id": "2611.27124", "title": "A Plan or an Adversarial Example? A Round-Trip Check for Latent World Models", "authors": ["Huiyuan Tian", "Chih-Yung Wen", "Shijian Li"], "abstract": "If we optimize an image until a classifier is confident it shows a cat, we may get an adversarial example, not a cat. Planning with a latent world model is a similar search for actions whose predicted future is closest to the goal. Is the result a plan, or an adversarial example of the world model? We show that it can be either. On the released DINO-WM and LeWM, more iterations of the cross-entropy method (CEM) lower the predicted cost but lose up to half of the problems CEM had already solved. The model's own predictions do not reveal these failures. We propose a simple test that executes the plan after every iteration and counts the problems a planner solves and then loses. Unlike an image, a plan comes with its actions, which our round-trip check reads back from the predicted states with a small network, penalizing mismatches. The check reads back the sum of each block of five actions, the part that two consecutive predicted states determine. Without retraining the world model and at only 0.2% to 3.1% more planning time, it improves the widely used planners CEM and MPPI on three released world models, and gains more where planners lose more problems. Without replanning, success rises from 0.39 to 0.76 on Wall with DINO-WM and from 0.56 to 0.94 for MPPI on JEPA-WM. With replanning (MPC), it rises from 0.70 to 0.81 on Cube with LeWM.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27124"}, {"id": "2611.27344", "title": "Learning Interaction Dynamics via Motion-Region Guidance for Robotic Video World Models", "authors": ["Yongkang He", "Xiaofen Xing", "Xiangmin Xu"], "abstract": "Action-conditioned video world models imagine future observations under candidate robot actions, providing a promising visual tool for robot policy evaluation and interaction simulation. However, existing video world models often optimize global reconstruction errors instead of emphasizing interaction-relevant regions. As a result, they may preserve overall scene appearance but overlook local interaction details, leading to physically implausible outcomes such as hallucinated contact effects and inconsistent robot-object interactions. We introduce MoReWorld, a unified motion-region-guided framework that uses a shared motion region, the part of the environment that moves in response to the robot's actions, to focus dynamics learning and video generation on interaction-relevant regions. The same motion region guides local motion prediction, region-aware supervision, and motion-gated future-feature conditioning. At inference time, the motion region is predicted as a motion probability map from visual history and robot actions, without requiring future observations or ground-truth motion labels. On WorldSimProbe, MoReWorld achieves the highest overall simulator-faithfulness score, with the strongest performance on local consistency, global consistency, and interaction dynamics. These results indicate that motion-region guidance helps the model preserve scene-level consistency while more faithfully predicting action-conditioned interaction dynamics.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27344"}, {"id": "2611.27638", "title": "Seeing Is Not Steering: Where Verifiable Reasoning Can Enter an End-to-End Driving Planner", "authors": ["Gautam Kumar Jain", "Atharva Mahindrakar", "Shubham Phoolari", "Ignacio Alvarez", "Carsten Markgraf", "Constanze Hungar", "Christoph Lauer", "Julian Staehler"], "abstract": "Driving models that reason may describe a hazard correctly while choosing their path for other reasons. We study where scene reasoning can enter an end-to-end planner so its influence can be checked. We freeze Drive-JEPA and use a fine-tuned vision-language model to state scene facts. Although fine-tuning improves fact accuracy, the two learned components we test show no detectable benefit from reading them. A rule-based fact check instead rejects or shortens paths that contradict the facts, linking each intervention to a stated fact. On the frozen planner alone, it gains 2.4 EPDMS points on navhard. Its 2.0-point margin over a control that changes the same frames without consulting facts remains statistically uncertain. A diagnostic using exact facts from maps and annotations yields a 3.6-point margin over its corresponding control, with a 95% confidence interval above zero. Separately, a path scorer and plan memory that read no stated facts raise navhard from 41.2 to 51.8. Bounding travel distance using the reasoner's facts adds 0.3 there and reduces navtest by 2.0. The fact check makes each intervention auditable, while the driving value of the reasoner's facts remains unresolved.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27638"}, {"id": "2611.27173", "title": "PACE-WM: Parallel World Modeling with Action History for Visual Planning", "authors": ["Haishan Liu", "Shijie Lian", "Bin Yu", "Yao Zhang", "Changti Wu", "Fanping Liu", "Jianzheng Liu", "Lei Xie", "Cong Huang", "Kai Chen"], "abstract": "JEPA-style world models support visual planning by predicting future representations conditioned on future actions. However, similar observations can conceal different motion states, making temporal context essential for interpreting future action effects. We propose PACE-WM, a parallel world model that uses executed-action history to contextualize future prediction and planning. Specifically, PACE-WM maintains a recurrent memory of executed actions and uses this memory to condition a causal Transformer. PACE-WM predicts multiple future representations in parallel without recursive predicted-state feedback within each prediction window. We further introduce Reference-Anchored Minimum Progress (RAMP) for action selection during planning. RAMP scores candidate actions by their predicted goal improvement along direct and split paths relative to a shared reference. Across four visual planning tasks, PACE-WM with RAMP achieves an average success rate of $98\\%$ and plans approximately $7$-$9\\times$ faster than autoregressive LeWM under matched CEM settings. We also construct four controlled benchmarks to evaluate PACE-WM's capabilities in motion disambiguation, goal-relative motion, and goal adaptation. Project page is available at https://github.com/LHS180/PACE-WM.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27173"}, {"id": "2611.27418", "title": "Beyond Future Views: Exploring Future-State World Models for Vision-Language Navigation", "authors": ["Kangyi Wu", "Pengna Li", "Yucheng Wang", "Yance Fang", "Xihan Ma", "Zhizhong Su", "Yang Wu", "Ye Deng", "Jinjun Wang", "Jianyi Liu"], "abstract": "Vision-Language Navigation(VLN) requires an embodied agent to follow language instructions through unseen 3D environments, where the target spaces often lie beyond the current observation. Navigation world models address this challenge by predicting future views either as pixels or latent representations, providing valuable look-ahead information for action decision. Both paradigms define the future primarily through what the agent may observe, raising a fundamental question: is predicting future views the ultimate form to represent the future for VLN? Cognitive studies show that the human hippocampus prospectively represents both future goals and intervening locations along planned routes. Inspired by this predictive-map view, we organize the navigation-relevant future around goal-directed spatial states and route structure. We instantiate this perspective with two complementary abstractions: a short-horizon waypoint that specifies the next local state to reach, and a mid-horizon corridor that captures the spatial support of the upcoming route. Based on this design, we propose FS-Nav, a future-state world modeling framework that predicts waypoint-corridor states from spatial memory and language instructions, and communicates them to a VLM navigator through top-down and first-person interfaces. Experiments on standard VLN benchmarks demonstrate that FS-Nav achieves state-of-the-art performance. This highlights navigation-relevant future-state modeling as a promising direction for representing the future in VLN.", "published": "2026-11-23", "comment": null, "url": "https://arxiv.org/abs/2611.27418"}]}}};
